    constructor(C _c) { c = _c; }

    // single public test driving two plays; amounts supplied as parameters
    function run(uint amt1, uint amt2) public payable {
        // require we send exactly the ticket amounts when calling play
        require(address(this).balance >= amt1 + amt2);
        // ticket amounts must match the contract constants; we don't read them, so require typical valid values
        // play 1
        c.play{value: amt1}();
        // record pot after first play
        uint potAfter1 = c.pot();
        // play 2
        c.play{value: amt2}();
        uint potAfter2 = c.pot();

        // The distinguishing property: if the pot did NOT reset after the first play (pot increased),
        // then after the second play the pot must not equal the single-ticket amount (i.e., it must be either reset to 0+ticket or be doubled).
        // Expressed without referencing random: when potAfter1 > 0 (meaning first play didn't zero it),
        // then potAfter2 != amt2 (the mutant flips which random value causes payouts and can make potAfter2 == amt2 unexpectedly).
        assert(!(potAfter1 > 0) || (potAfter2 != amt2));
    }

    // allow receiving ETH for the test
    receive() external payable {}
}

