    // amount must equal C.TICKET_AMOUNT; we take it as parameter to avoid hard-coding
    function run(uint ticketAmount, uint feeAmount) public payable {
        // ensure this test caller has enough balance to forward payments
        require(address(this).balance >= msg.value);

        // Preconditions: ticketAmount must match contract's constant TICKET_AMOUNT and feeAmount must match FEE_AMOUNT
        // we read those via public getters: TICKET_AMOUNT and FEE_AMOUNT are constants but not getters; however bank and pot are public
        // so we require the provided amounts to be positive and rely on behavior observable via pot and balances.

        // First, buy one ticket to seed the pot
        require(ticketAmount > 0);
        c.play{value: ticketAmount}();

        // Read pot after first buy (should equal ticketAmount on original contract)
        uint potAfterFirst = c.pot();
        // Buy a second ticket which will be the winning play in P when random==0
        c.play{value: ticketAmount}();

        // Observe resulting pot and contract balance
        uint potAfterSecond = c.pot();
        uint contractBal = address(c).balance;

        // The distinguishing property: if a play caused a payout that emptied the pot then after the winning play pot==0.
        // We assert that potAfterSecond is strictly less than potAfterFirst + ticketAmount + 1 to ensure pot got drained to zero
        // (On P pot becomes 0 after a win; on M it stays >0). We capture this by asserting potAfterSecond == 0.
        assert(potAfterSecond == 0);
    }

    // allow this test contract to receive ether forwarded in transactions
    receive() external payable {}
