    // We let the fuzzer pick the caller. We also fuzz a nonzero seed to vary block.timestamp via vm.warp.
    function testFuzz_property(address player, uint256 warpDelta) public {
        // Keep the player as a nonzero address (EOA) and warpDelta in a wide range
        vm.assume(player != address(0));
        warpDelta = bound(warpDelta, 0, 10_000); // keep warpDelta reasonable but wide

        // Give the player enough ETH to buy a ticket
        vm.deal(player, 100 ether);

        // Move time to vary keccak256(block.timestamp, block.difficulty) randomness
        vm.warp(block.timestamp + warpDelta);

        // Make the call from the fuzzed player sending exactly the ticket amount
        uint256 ticket = 10; // matches C.TICKET_AMOUNT
        vm.prank(player);
        bool ok;
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule to assert: If the call completed and transferred out winnings (which we
        // detect by observing that the contract's pot is zero afterwards), then the reference
        // implementation always sets pot == 0; we assert that pot is either zero or, if the call
        // did not take the winning branch/transfer, pot is non-negative (always true). More simply,
        // for the correct contract: after any successful play() sending a ticket, pot == 0 OR
        // pot == ticket (if no payout happened because branch not taken). We assert that pot <= ticket.
        // This captures that when a payout happens pot becomes 0 and the mutant that fails to reset
        // pot may leave pot > ticket (accumulating previous pot), which the fuzzer can find.

        // Observe only via public getter c.pot()
        uint256 observedPot = c.pot();

        // The invariant we assert: after a single play() by any player sending the exact ticket,
        // the contract's pot must be either 0 (payout happened and pot reset) or exactly ticket (no payout and pot equals the single added ticket).
        // The mutant that omits resetting pot can have observedPot > ticket after a winning payout (violating this property) for some inputs.
        assertTrue(observedPot == 0 || observedPot == ticket);
    }
}

