        uint256 potAfter = c.pot();
        uint256 cBalanceAfter = address(c).balance;

        // If the contract paid out to the player (winning branch), P ensures pot==0 and bank gained exactly 1.
        // We assert: if pot is zero after the call then bankAfter == bankBefore + 1
        assert(!(potAfter == 0) || (bankAfter == bankBefore + 1));
